require_once __DIR__.'/includes/functions.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$s=db()->prepare('SELECT * FROM products WHERE id=? AND active=1');$s->execute([$id?:0]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Product not found');}$page_title=$p['name'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$qty=max(1,min(10,(int)($_POST['quantity']??1)));if((int)$p['stock']<$qty){flash('error','Not enough stock available.');redirect('product.php?id='.$p['id']);}$_SESSION['cart'][$p['id']]=min(20,(int)($_SESSION['cart'][$p['id']]??0)+$qty);flash('success','Added to your bag.');redirect('cart.php');}
include __DIR__.'/includes/header.php'; ?>
<div class="container py-5"><div class="row g-5"><div class="col-md-6"><img class="product-detail-image" src="<?= e($p['image_url']) ?>" alt="<?= e($p['name']) ?>"></div><div class="col-md-6 py-lg-5"><span class="eyebrow"><?= e($p['category']) ?> · Style edit</span><h1 class="section-title mt-3"><?= e($p['name']) ?></h1><p class="fs-4 fw-bold"><?= money($p['sale_price'] ?: $p['price']) ?> <?php if($p['sale_price'] && $p['sale_price']<$p['price']): ?><small class="old-price"><?= money($p['price']) ?></small><?php endif; ?></p><p class="muted"><?= nl2br(e($p['description'])) ?></p><p class="small"><?= (int)$p['stock']>0?'In stock · Ready to ship':'Currently out of stock' ?></p><form method="post" class="mt-4"><?= csrf_field() ?><label class="form-label" for="quantity">Quantity</label><input id="quantity" class="form-control quantity-input mb-3" type="number" name="quantity" min="1" max="<?= min(10,(int)$p['stock']) ?>" value="1" <?= (int)$p['stock']<1?'disabled':'' ?>><button class="btn btn-dark" <?= (int)$p['stock']<1?'disabled':'' ?>>Add to bag <i class="bi bi-bag ms-2"></i></button></form><hr class="my-4"><p><i class="bi bi-truck me-2"></i>Free shipping on orders over ₹1,499</p><p><i class="bi bi-arrow-repeat me-2"></i>7-day return window on eligible items</p></div></div></div>
